import{_ as a,y as n,a as l,o as g,a2 as o,D as i,g as s,I as t}from"./chunks/framework.DCcmcJcL.js";const C=JSON.parse('{"title":"Roles","description":"","frontmatter":{},"headers":[],"relativePath":"settings/roles.md","filePath":"settings/roles.md","lastUpdated":1789441803000}'),h={name:"settings/roles.md"};function d(p,e,m,c,u,f){const r=n("ImagePopup");return g(),l("div",null,[e[2]||(e[2]=o('<h1 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h1><p>A role is a set of permissions. Every admin user has one role, so roles control which parts of the admin panel each person can open and what they can do there.</p><p>Bagisto comes with the <strong>Administrator</strong> role, which has every permission. Create other roles for team members who need less access, such as someone who only handles orders.</p><h2 id="your-roles" tabindex="-1">Your roles <a class="header-anchor" href="#your-roles" aria-label="Permalink to &quot;Your roles&quot;">​</a></h2><p>Go to <strong>Settings &gt;&gt; Roles</strong> to see every role with its <strong>Id</strong>, <strong>Name</strong> and <strong>Permission Type</strong>: <code>all</code> for a role with every permission, or <code>custom</code> for one with chosen permissions.</p>',5)),i(r,{src:"/images/settings/roles.png",alt:"Roles grid with the Administrator and Catalog Manager roles"}),e[3]||(e[3]=s("h2",{id:"create-a-role",tabindex:"-1"},[t("Create a role "),s("a",{class:"header-anchor",href:"#create-a-role","aria-label":'Permalink to "Create a role"'},"​")],-1)),s("ol",null,[e[1]||(e[1]=o("<li><p>Go to <strong>Settings &gt;&gt; Roles</strong>.</p></li><li><p>Click <strong>Create Role</strong>.</p></li><li><p>In <strong>Access Control</strong>, choose the <strong>Permissions</strong>: <strong>Custom</strong> lets you choose them, and <strong>All</strong> gives the role every permission. <strong>Custom</strong> is selected at first.</p></li><li><p>If you chose <strong>Custom</strong>, select each permission the role needs in the permission tree.</p></li><li><p>In <strong>General</strong>, enter the <strong>Name</strong> and <strong>Description</strong>.</p></li>",5)),s("li",null,[e[0]||(e[0]=s("p",null,[t("Click "),s("strong",null,"Save Role"),t(".")],-1)),i(r,{src:"/images/settings/create-role.png",alt:"Create Role page for an Order Manager role with order, invoice and shipment permissions selected"})])]),e[4]||(e[4]=o('<p>The message <em>Roles Created Successfully</em> appears and the role is listed. You can now choose it when you <a href="./users.html">create a user</a>.</p><p>A role with <strong>Custom</strong> permissions needs at least one permission. If a role ends up with none, its users are signed out.</p><h2 id="find-the-right-permissions" tabindex="-1">Find the right permissions <a class="header-anchor" href="#find-the-right-permissions" aria-label="Permalink to &quot;Find the right permissions&quot;">​</a></h2><ul><li>The permission tree follows the admin menu. Each group matches a menu item, such as <strong>Sales</strong> or <strong>Catalog</strong>, and holds the actions inside it, such as <strong>Create</strong>, <strong>View</strong> or <strong>Edit</strong>.</li><li>Every group starts expanded. Click the arrow beside a group to collapse or expand it.</li><li>Type in <strong>Search permissions</strong> to find a permission by name.</li><li>Selecting a permission also selects the groups above it and every permission under it.</li><li>Clearing a group clears everything under it. Clearing a single permission leaves its group selected.</li></ul><h2 id="what-a-user-with-a-custom-role-sees" tabindex="-1">What a user with a custom role sees <a class="header-anchor" href="#what-a-user-with-a-custom-role-sees" aria-label="Permalink to &quot;What a user with a custom role sees&quot;">​</a></h2><ul><li>Menu items and buttons for things the role can&#39;t do are hidden.</li><li>If the user opens a page the role doesn&#39;t allow, for example from a bookmark, a <strong>401 Unauthorized</strong> page is shown.</li><li>If the role doesn&#39;t include <strong>Dashboard</strong>, the user goes straight to the first page the role allows when they sign in.</li></ul><h2 id="edit-or-delete-a-role" tabindex="-1">Edit or delete a role <a class="header-anchor" href="#edit-or-delete-a-role" aria-label="Permalink to &quot;Edit or delete a role&quot;">​</a></h2><p>To edit a role:</p><ol><li>Go to <strong>Settings &gt;&gt; Roles</strong>.</li><li>Click the edit icon of the role.</li><li>Change the role&#39;s details or permissions.</li><li>Click <strong>Save Role</strong>.</li></ol><p>The message <em>Roles is updated successfully</em> appears.</p><p>To remove a role:</p><ol><li>Go to <strong>Settings &gt;&gt; Roles</strong>.</li><li>Click the delete icon of the role.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><ul><li>A role that is assigned to a user can&#39;t be deleted. Give those users another role first.</li><li>The last role can&#39;t be deleted.</li><li>While only one user has a role with <strong>All</strong> permissions, no role can be changed from <strong>All</strong> to <strong>Custom</strong>. Give a second user full access first.</li></ul>',13))])}const w=a(h,[["render",d]]);export{C as __pageData,w as default};
